def transform(grid):
    # Marker pixels live on the thick 5-colored grid lines. Read their
    # positions as a coarse color map, preserving blank cells as background.
    markers = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v not in (0, 5, 9):
                markers[(r, c)] = v
    # infer the repeating grid's line coordinates from marker locations
    rs = sorted({r for r, c in markers})
    cs = sorted({c for r, c in markers})
    return [[markers.get((r,c), 9) for c in cs] for r in rs]
